<?php
require_once __DIR__ . '/../app/auth.php';
require_once __DIR__ . '/../app/helpers.php';
$user = require_admin();
ensure_v44_tables();
ensure_student_money_tables();
$db = db();
$message = '';

$leireUser = $db->query("SELECT id,name,username FROM users WHERE username='leire' LIMIT 1")->fetch();
$leireId = $leireUser ? (int)$leireUser['id'] : 0;
if ($leireId) ensure_student_profile($leireId);

if ($_SERVER['REQUEST_METHOD'] === 'POST' && $leireId) {
    $action = $_POST['action'] ?? '';
    if ($action === 'adjust_money') {
        $amount = parse_money_to_cents((string)($_POST['amount'] ?? '0'));
        $direction = $_POST['direction'] ?? 'deposit';
        $reason = trim((string)($_POST['reason'] ?? 'Ajuste manual de Juanra')) ?: 'Ajuste manual de Juanra';
        if ($direction === 'withdraw') $amount = -abs($amount); else $amount = abs($amount);
        $message = wallet_adjust_balance($leireId, $amount, $reason, (int)$user['id'], $direction === 'withdraw' ? 'admin_withdraw' : 'admin_deposit')
            ? 'Saldo actualizado correctamente.'
            : 'No se pudo actualizar el saldo. Revisa la cantidad o el saldo disponible.';
    } elseif ($action === 'withdrawal_action') {
        $message = handle_withdrawal_admin_action((int)($_POST['request_id'] ?? 0), (string)($_POST['request_action'] ?? ''), (int)$user['id'], (string)($_POST['admin_note'] ?? ''));
    } elseif ($action === 'save_reward_rule') {
        $ruleId = (int)($_POST['rule_id'] ?? 0);
        $ruleMode = (string)($_POST['rule_mode'] ?? 'examen');
        $minScore = (float)str_replace(',', '.', (string)($_POST['min_score'] ?? '10'));
        $amountCents = (int)($_POST['amount_cents'] ?? 0);
        $active = !empty($_POST['active']);
        $message = save_reward_rule($ruleId, $ruleMode, $minScore, $amountCents, $active);
    } elseif ($action === 'avatar_upload' && isset($_FILES['avatar'])) {
        $message = save_profile_avatar_upload($leireId, $_FILES['avatar']);
    } elseif ($action === 'subject_done' || $action === 'subject_clear') {
        set_subject_official_exam_done($leireId, (string)($_POST['subject'] ?? ''), $action === 'subject_done', (string)($_POST['note'] ?? ''));
        $message = $action === 'subject_done' ? 'Asignatura marcada como examen oficial hecho.' : 'Asignatura reactivada para recomendaciones.';
    } elseif ($action === 'topic_done' || $action === 'topic_clear') {
        set_topic_official_exam_done($leireId, (int)($_POST['topic_id'] ?? 0), $action === 'topic_done', (string)($_POST['note'] ?? ''));
        $message = $action === 'topic_done' ? 'Tema marcado como examen oficial hecho.' : 'Tema reactivado para recomendaciones.';
    }
}

$topics = $db->query('SELECT t.*, COUNT(DISTINCT q.id) questions, COUNT(DISTINCT f.id) files FROM topics t LEFT JOIN questions q ON q.topic_id=t.id LEFT JOIN topic_files f ON f.topic_id=t.id GROUP BY t.id ORDER BY FIELD(t.subject,"Matemáticas","Lengua","Conocimiento del Medio","Inglés"), t.id ASC')->fetchAll();
$results = $db->query('SELECT r.*, u.name user_name, t.title topic_title, t.subject FROM results r JOIN users u ON u.id=r.user_id JOIN topics t ON t.id=r.topic_id ORDER BY r.created_at DESC LIMIT 12')->fetchAll();
$stat = $db->query('SELECT COUNT(*) total_results, ROUND(AVG(score),2) avg_score, SUM(correct_questions) corrects, SUM(total_questions-correct_questions) errors FROM results')->fetch() ?: [];
$bySubject = $db->query('SELECT t.subject, ROUND(AVG(r.score),2) avg_score, COUNT(r.id) tries FROM topics t LEFT JOIN results r ON r.topic_id=t.id GROUP BY t.subject ORDER BY FIELD(t.subject,"Matemáticas","Lengua","Conocimiento del Medio","Inglés")')->fetchAll();
$subjects = ['Matemáticas','Lengua','Conocimiento del Medio','Inglés'];
$leireProfile = $leireId ? ensure_student_profile($leireId) : null;
$xpHistory = $leireId ? $db->query('SELECT * FROM xp_history WHERE user_id='.$leireId.' ORDER BY created_at DESC LIMIT 10')->fetchAll() : [];
$walletHistory = $leireId ? wallet_transactions_for_user($leireId, 12) : [];
$withdrawals = withdrawal_requests_for_admin(30);
$rewardRules = reward_rules_for_admin();
$frequent = $leireId ? frequent_error_topics($leireId, 8) : [];
$weekly = $leireId ? weekly_summary_for_user($leireId) : ['total'=>0,'avg_score'=>0,'corrects'=>0,'errors'=>0,'best'=>null,'weak'=>null];
$tasks = $leireId ? ensure_daily_tasks($leireId) : [];
$shopCount = $leireId ? count(array_filter(shop_items_for_user($leireId), fn($i) => !empty($i['owned_id']))) : 0;
$subjectDone = $leireId ? subject_official_done_map($leireId) : [];
$topicDone = $leireId ? topic_official_done_map($leireId, array_map(fn($t)=>(int)$t['id'], $topics)) : [];
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Panel Juanra</title><link rel="stylesheet" href="../public/assets/css/style.css?v=5.15"><style>.admin-dashboard-hero{background:linear-gradient(135deg,rgba(25,18,70,.96),rgba(11,12,42,.96));border:1px solid rgba(132,92,255,.28);padding:24px;border-radius:22px}.admin-dashboard-hero h1{margin:.25rem 0 0;font-size:clamp(1.7rem,3vw,2.5rem);letter-spacing:-.04em}.eyebrow{font-size:.68rem;letter-spacing:.18em;color:#a996ff;font-weight:800}.admin-quick-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-top:22px}.admin-quick{display:flex;align-items:center;gap:10px;padding:14px;border-radius:15px;color:#fff;text-decoration:none;border:1px solid rgba(255,255,255,.1);min-width:0}.admin-quick b{width:38px;height:38px;border-radius:11px;display:grid;place-items:center;background:rgba(255,255,255,.16);font-size:1.25rem}.admin-quick span{display:grid;gap:2px;min-width:0}.admin-quick strong{font-size:.78rem}.admin-quick small{font-size:.65rem;opacity:.72}.admin-quick em{margin-left:auto;font-size:1.4rem;font-style:normal}.admin-quick.purple{background:linear-gradient(135deg,#5d2be8,#9d3df2)}.admin-quick.green{background:linear-gradient(135deg,#087c69,#0c9e8c)}.admin-quick.blue{background:linear-gradient(135deg,#0757b8,#176ee5)}.admin-quick.orange{background:linear-gradient(135deg,#a64b18,#d47722)}@media(max-width:800px){.admin-quick-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:480px){.admin-quick-grid{grid-template-columns:1fr}}</style></head><body><div class="wrap">
<header class="topbar"><div class="brand">⚙️ Panel de Juanra <span class="pill">V5.15</span></div><nav class="nav"><a class="secondary" href="../public/dashboard.php">App Leire</a><a class="secondary" href="../public/wallet.php">Dinero</a><a class="secondary" href="../public/profile.php">Perfil</a><a class="secondary" href="../public/trainer.php">Entrenador</a><a class="secondary" href="../public/shop.php">Tienda</a><a class="secondary" href="scans.php">Escaneos</a><a class="secondary" href="dazn.php">📺 Cuentas DAZN</a><a class="secondary" href="ai_settings.php">IA</a><a class="secondary" href="../public/logout.php">Salir</a></nav></header>
